Find the value of $x$ that satisfies $\frac{\sqrt{5x}}{\sqrt{3(x-1)}}=2$. Express your answer in simplest fractional form.

Put your final answer within \boxed{}.

#include <iostream>
#include <cmath>

int main() {
    double x;
    double sqrt5x = sqrt(5 * x);
    double sqrt3x1 = sqrt(3 * (x - 1));
    double equation = sqrt5x / sqrt3x1;
    double solution = 2;
    double difference = solution - equation;
    double absoluteDifference = std::abs(difference);
    double tolerance = 0.0001;
    while (absoluteDifference > tolerance) {
        x += difference;
        sqrt5x = sqrt(5 * x);
        sqrt3x1 = sqrt(3 * (x - 1));
        equation = sqrt5x / sqrt3x1;
        difference = solution - equation;
        absoluteDifference = std::abs(difference);
    }
    std::cout << "The value of x that satisfies the equation is: " << x << std::endl;
    return 0;
}

