double slope = (y2 - y1) / (x2 - x1);

// Calculate the y-intercept of the line segment
double y_intercept = y1 - slope * x1;

// Calculate the slope of the perpendicular bisector
double perpendicular_slope = -1 / slope;

// Calculate the y-intercept of the perpendicular bisector
